<?php
require dirname(__DIR__).'/public/database.php';require dirname(__DIR__).'/public/schema.php';
$cfg=appConfig();if(!str_starts_with($cfg['db_name']??'','itu_test_')||!in_array($cfg['db_host']??'',['127.0.0.1','localhost'],true))exit(2);
$pdo=appDatabase();appSchema($pdo);$_SESSION=[];$passed=0;$users=[];$files=[];
function must($ok,$message){if(!$ok)throw new RuntimeException($message);}
function rejected($fn){try{$fn();}catch(RuntimeException $e){if($e instanceof PDOException)throw $e;return;}throw new RuntimeException('Expected rejection');}
function checkImage($name,$fn){global $passed;$fn();$passed++;echo "PASS $name\n";}
function imageUser(){global $pdo,$users;opsExec($pdo,'INSERT INTO users(phone,password,biz_name,biz_category,location) VALUES(?,?,?,?,?)',['img-'.bin2hex(random_bytes(7)),password_hash('Local-test-only',PASSWORD_DEFAULT),'Image test','cafe','Тараз']);$id=(int)$pdo->lastInsertId();$users[]=$id;return $id;}
function imageInput($text='A ceramic cup of coffee on a wooden table'){return ['request_key'=>bin2hex(random_bytes(16)),'prompt'=>$text];}
$u=imageUser();$other=imageUser();$account=bin2hex(random_bytes(16));$token='test_'.bin2hex(random_bytes(20));
$connect=['account_id'=>$account,'token'=>$token,'free_plan'=>true];$models=fn()=>[['name'=>IMAGE_AI_MODEL]];
$im=imagecreatetruecolor(512,512);imagefill($im,0,0,imagecolorallocate($im,25,60,45));ob_start();imagejpeg($im,null,90);$raw=ob_get_clean();imagedestroy($im);$image=fn()=>['image'=>base64_encode($raw)];
try{
    checkImage('another database connection cannot start a concurrent worker',function()use($pdo,$cfg){$second=appDatabase();$second->query("SELECT GET_LOCK('aulieata.image-ai',0)");try{rejected(fn()=>imageAiRun($pdo,$cfg,fn()=>throw new RuntimeException('Must not call provider')));}finally{$second->query("SELECT RELEASE_LOCK('aulieata.image-ai')");}});
    checkImage('free plan confirmation, account validation and model permission check',function()use($pdo,$u,$connect,$cfg,$models){rejected(fn()=>imageAiConnect($pdo,$u,$connect+[], $cfg,fn()=>[]));$bad=$connect;$bad['free_plan']=false;rejected(fn()=>imageAiConnect($pdo,$u,$bad,$cfg,$models));$bad=$connect;$bad['account_id']='https://evil.example';rejected(fn()=>imageAiConnect($pdo,$u,$bad,$cfg,$models));});
    checkImage('encrypted token and tenant-scoped connection',function()use($pdo,$u,$other,$connect,$cfg,$models,$token){imageAiConnect($pdo,$u,$connect,$cfg,$models);$stored=opsOne($pdo,'SELECT token_box FROM image_ai_connections WHERE user_id=?',[$u]);must($stored['token_box']!==$token&&openToken($stored['token_box'],$cfg)===$token,'encryption');must(!str_contains(opsJson(imageAiStatus($pdo,$u)),$token),'status token leak');must(!imageAiStatus($pdo,$other)['connected'],'other tenant connection');});
    $input=imageInput();$job=imageAiQueue($pdo,$u,$input);
    checkImage('idempotent queue, mismatch and cross-tenant cancellation',function()use($pdo,$u,$other,$input,$job){must(imageAiQueue($pdo,$u,$input)['id']===$job['id'],'duplicate job');$bad=$input;$bad['prompt'].=' changed';rejected(fn()=>imageAiQueue($pdo,$u,$bad));rejected(fn()=>imageAiCancel($pdo,$other,$job['id']));must(!imageAiList($pdo,$other),'other tenant library');});
    checkImage('one provider call, private JPEG and no automatic publication',function()use($pdo,$u,$cfg,$image,$job,&$files){$calls=0;imageAiRun($pdo,$cfg,function()use(&$calls,$image){$calls++;return $image();});imageAiRun($pdo,$cfg,function()use(&$calls,$image){$calls++;return $image();});$r=opsOne($pdo,'SELECT * FROM image_ai_jobs WHERE id=?',[$job['id']]);$files[]=imageAiPath($r['image_key']);must($calls===1&&$r['status']==='done','single call');must(is_file(end($files))&&getimagesize(end($files))[0]===512,'private image saved');must((int)opsOne($pdo,'SELECT COUNT(*) n FROM social_posts WHERE user_id=?',[$u])['n']===0,'no social publication');});
    checkImage('cancel wins before worker, reconnect invalidates queued jobs',function()use($pdo,$u,$cfg,$image,$connect,$models){$r=imageAiQueue($pdo,$u,imageInput());imageAiCancel($pdo,$u,$r['id']);$calls=0;imageAiRun($pdo,$cfg,function()use(&$calls,$image){$calls++;return $image();});must($calls===0,'cancelled call');$r=imageAiQueue($pdo,$u,imageInput());imageAiConnect($pdo,$u,$connect,$cfg,$models);must(opsOne($pdo,'SELECT status FROM image_ai_jobs WHERE id=?',[$r['id']])['status']==='cancelled','old credentials queued');});
    checkImage('malformed image and uncertain failure consume quota without retries',function()use($pdo,$u,$cfg){$a=imageAiQueue($pdo,$u,imageInput());imageAiRun($pdo,$cfg,fn()=>['image'=>base64_encode('<html>not an image</html>')]);$b=imageAiQueue($pdo,$u,imageInput());$calls=0;imageAiRun($pdo,$cfg,function()use(&$calls){$calls++;throw new RuntimeException('Provider timeout');});imageAiRun($pdo,$cfg,function()use(&$calls){$calls++;return [];});must($calls===1,'timeout retried');foreach([$a,$b] as $r)must(opsOne($pdo,'SELECT status FROM image_ai_jobs WHERE id=?',[$r['id']])['status']==='failed','failed status');must(imageAiStatus($pdo,$u)['used']===3,'attempt accounting');});
    checkImage('stale processing is terminal, pending cap and user daily ceiling',function()use($pdo,$u,$cfg){$a=imageAiQueue($pdo,$u,imageInput());$b=imageAiQueue($pdo,$u,imageInput());rejected(fn()=>imageAiQueue($pdo,$u,imageInput()));opsExec($pdo,"UPDATE image_ai_jobs SET status='processing',attempted_day=? WHERE id=?",[gmdate('Y-m-d'),$a['id']]);imageAiRun($pdo,$cfg,fn()=>['image'=>'bad']);must(imageAiStatus($pdo,$u)['used']===5,'daily attempts');rejected(fn()=>imageAiQueue($pdo,$u,imageInput()));must(opsOne($pdo,'SELECT status FROM image_ai_jobs WHERE id=?',[$a['id']])['status']==='failed','stale status');});
    checkImage('shared Cloudflare account ceiling cannot be multiplied by tenants',function()use($pdo,$other,$connect,$cfg,$models,$u){imageAiConnect($pdo,$other,$connect,$cfg,$models);for($i=0;$i<45;$i++)opsExec($pdo,"INSERT INTO image_ai_jobs(user_id,request_key,input_hash,account_id,revision,prompt,status,attempted_day,created_at,updated_at) VALUES(?,?,?,?,?,?,'failed',?,?,?)",[$u,bin2hex(random_bytes(16)),hash('sha256','test'),$connect['account_id'],str_repeat('0',32),'Quota fixture',gmdate('Y-m-d'),imageAiNow(),imageAiNow()]);must(imageAiStatus($pdo,$other)['remaining']===0,'shared ceiling');rejected(fn()=>imageAiQueue($pdo,$other,imageInput()));});
    checkImage('disconnect removes local credential and prevents queueing',function()use($pdo,$other){imageAiDisconnect($pdo,$other);$r=opsOne($pdo,'SELECT * FROM image_ai_connections WHERE user_id=?',[$other]);must(!$r['active']&&$r['token_box']==='','credential retained');rejected(fn()=>imageAiQueue($pdo,$other,imageInput()));});
    echo "RESULT $passed passed; provider mocked, no network or publishing.\n";
}finally{foreach($files as $file)if(is_file($file))unlink($file);foreach($users as $id){opsExec($pdo,'DELETE FROM image_ai_jobs WHERE user_id=?',[$id]);opsExec($pdo,'DELETE FROM image_ai_connections WHERE user_id=?',[$id]);opsExec($pdo,'DELETE FROM users WHERE id=?',[$id]);}}
